import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"定义编辑器","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/editor.md","filePath":"modules/skills/editor.md","lastUpdated":0}`),a={name:`modules/skills/editor.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="定义编辑器" tabindex="-1">定义编辑器 <a class="header-anchor" href="#定义编辑器" aria-label="Permalink to “定义编辑器”">​</a></h1><p>这页讲 EmakiSkills 的游戏内定义编辑器: 怎么打开, 浏览器和编辑页两个界面怎么用, 能编辑哪些定义, 修改怎么校验和保存, 以及 edit-backups 备份机制</p><p>编辑器面向服主和配置者: 不出游戏, 不碰文本编辑器, 就能浏览, 新建, 修改和删除 <code>skills/</code> 与 <code>resources/</code> 下的定义文件. 技能字段和资源字段本身怎么配, 还是看 <a href="./definitions.html">技能定义</a>; 这页只讲编辑器本身</p><h2 id="打开编辑器" tabindex="-1">打开编辑器 <a class="header-anchor" href="#打开编辑器" aria-label="Permalink to “打开编辑器”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>效果</th></tr></thead><tbody><tr><td><code>/eskills edit</code></td><td>打开定义浏览器, 列出全部分类和定义文件</td></tr><tr><td><code>/eskills edit &lt;id&gt;</code></td><td>直接打开该定义的编辑页; id 支持 Tab 补全 (补全范围是技能定义与本地资源的全部 id)</td></tr></tbody></table><p>权限是 <code>emakiskills.edit</code> 或 <code>emakiskills.admin</code> (默认 op), 且<strong>只接受玩家执行</strong>: 控制台执行会提示仅限玩家. id 认不出来时回复&quot;无法打开 %id% 的编辑界面&quot;</p><h2 id="能编辑哪些定义" tabindex="-1">能编辑哪些定义 <a class="header-anchor" href="#能编辑哪些定义" aria-label="Permalink to “能编辑哪些定义”">​</a></h2><p>浏览器按分类浏览, 每个分类对应一个目录:</p><table tabindex="0"><thead><tr><th>分类</th><th>位置</th><th>新建骨架</th></tr></thead><tbody><tr><td>技能定义</td><td><code>skills/*.yml</code></td><td><code>id</code>, <code>display_name</code>, <code>description</code>, <code>icon_material</code>, <code>trigger_type</code>, <code>cooldown_ticks</code>, <code>global_cooldown_ticks</code>, <code>tags</code>, <code>tab_tags</code>, <code>conflicting_skills</code>, <code>required_skills</code>, <code>show_in_slots</code>, <code>ui_category</code>, <code>sort_order</code>, <code>enabled</code>, <code>resource_costs</code>, <code>variables</code>, <code>script</code>, <code>upgrade</code></td></tr><tr><td>本地资源</td><td><code>resources/*.yml</code></td><td><code>id</code>, <code>display_name</code>, <code>max</code>, <code>default_current</code>, <code>regen_amount</code>, <code>regen_interval_ticks</code>, <code>clamp_min</code>, <code>clamp_max</code></td></tr></tbody></table><ul><li>文件的 ID 取文件内容里的 <code>id</code>, 读不到时退回文件名 (去掉扩展名).</li><li>新建定义时会按骨架预填字段; 技能骨架里 <code>script</code> 预填 <code>mode: native</code> 的空动作管道, <code>upgrade</code> 预填 <code>max_level: 1</code> 的关闭状态, 你再逐项改.</li><li>发货的示例技能 (<code>example_*.yml</code>) 和示例脚本技能也是普通定义文件, 同样可以浏览和编辑, 不想要就删掉</li></ul><h2 id="定义浏览器-editor-browser-gui-yml" tabindex="-1">定义浏览器 (editor_browser_gui.yml) <a class="header-anchor" href="#定义浏览器-editor-browser-gui-yml" aria-label="Permalink to “定义浏览器 (editor_browser_gui.yml)”">​</a></h2><p><code>/eskills edit</code> 无参打开的就是定义浏览器: 跨分类列出定义文件, 每页一屏. 界面模板是 <code>gui/editor_browser_gui.yml</code>, 5 行布局 (第 1 行返回/关闭, 2-4 行内容, 5 行翻页与新建):</p><table tabindex="0"><thead><tr><th>槽位键</th><th>类型</th><th>默认位置</th><th>含义</th></tr></thead><tbody><tr><td><code>doc_entry</code></td><td><code>field_entry</code></td><td>2-4 行内容区</td><td>定义条目; 左键打开进入编辑页, 右键删除 (二次确认, 删前自动备份)</td></tr><tr><td><code>back</code></td><td><code>back</code></td><td>0</td><td>返回/关闭浏览界面</td></tr><tr><td><code>close</code></td><td><code>close</code></td><td>8</td><td>关闭浏览界面</td></tr><tr><td><code>page_prev</code></td><td><code>page_prev</code></td><td>36</td><td>上一页</td></tr><tr><td><code>page_info</code></td><td><code>page_info</code></td><td>38</td><td>当前页码与定义数 (<code>%current_page%</code>, <code>%total_pages%</code>, <code>%menu_title%</code>, <code>%entry_count%</code>)</td></tr><tr><td><code>page_next</code></td><td><code>page_next</code></td><td>40</td><td>下一页</td></tr><tr><td><code>new_doc</code></td><td><code>new_doc</code></td><td>42</td><td>新建定义: 先选分类, 再在聊天栏输入新定义的 ID</td></tr><tr><td><code>border</code></td><td><code>filler</code></td><td>其余格子</td><td>边框填充, 不可交互</td></tr></tbody></table><p>新建规则: ID 只允许小写字母, 数字和下划线 (例如 <code>my_skill</code>); 非法 ID, 与已有定义重名, 或该分类不支持新建时都会拒绝并给出提示 (技能与本地资源两个分类都支持新建和删除). 删除要按两次: 第一次点&quot;删除&quot;出确认界面, 再点&quot;确认删除&quot;才执行, 中途点&quot;取消&quot;什么都不动</p><h2 id="编辑页-editor-page-gui-yml" tabindex="-1">编辑页 (editor_page_gui.yml) <a class="header-anchor" href="#编辑页-editor-page-gui-yml" aria-label="Permalink to “编辑页 (editor_page_gui.yml)”">​</a></h2><p>点开某个定义 (或 <code>/eskills edit &lt;id&gt;</code>) 进入编辑页. 所有子菜单共用 <code>gui/editor_page_gui.yml</code>, 标题随当前子菜单替换, 字段渲染进内容区网格:</p><table tabindex="0"><thead><tr><th>槽位键</th><th>类型</th><th>默认位置</th><th>含义</th></tr></thead><tbody><tr><td><code>preview</code></td><td><code>preview</code></td><td>4</td><td>定义预览: 按草稿里的 <code>icon_material</code> / <code>display_name</code> 生成一个展示物品</td></tr><tr><td><code>field_entry</code></td><td><code>field_entry</code></td><td>2-4 行内容区</td><td>字段条目, 操作方式见下表</td></tr><tr><td><code>back_parent</code></td><td><code>back_parent</code></td><td>0</td><td>返回上一级菜单</td></tr><tr><td><code>back_home</code></td><td><code>back_home</code></td><td>1</td><td>返回编辑器主页</td></tr><tr><td><code>close</code></td><td><code>close</code></td><td>8</td><td>关闭编辑界面</td></tr><tr><td><code>confirm</code></td><td><code>confirm</code></td><td>36</td><td>&quot;添加&quot;: 向当前列表新增一项</td></tr><tr><td><code>page_prev</code></td><td><code>page_prev</code></td><td>38</td><td>上一页</td></tr><tr><td><code>page_info</code></td><td><code>page_info</code></td><td>40</td><td>当前页码与条目数</td></tr><tr><td><code>page_next</code></td><td><code>page_next</code></td><td>42</td><td>下一页</td></tr><tr><td><code>border</code></td><td><code>filler</code></td><td>其余格子</td><td>边框填充, 不可交互</td></tr></tbody></table><p>技能定义的深层字段各有子菜单: 释放条件, 技能变量, 技能脚本 (含 cast/hit/miss/fail 动作阶段), 升级配置 (含升级经济), 资源消耗条目. 字段操作 (提示文案就是这么写的):</p><table tabindex="0"><thead><tr><th>字段形态</th><th>操作</th></tr></thead><tbody><tr><td>开关</td><td>左键切换 开/关, 右键重置</td></tr><tr><td>枚举</td><td>左键切换到下一个取值, 右键重置</td></tr><tr><td>数值</td><td>左键在聊天栏输入数值, 右键重置</td></tr><tr><td>文本</td><td>左键在聊天栏输入文本, 右键重置</td></tr><tr><td>子菜单</td><td>左键进入</td></tr><tr><td>列表</td><td>左键查看; 序列列表: 左键加一行, Shift+左键改条目, 右键删最后一行, Shift+右键清空</td></tr><tr><td>映射</td><td>左键改条目 (聊天栏按&quot;键=值&quot;输入), 右键重置整个节点</td></tr></tbody></table><p>聊天栏输入时输入 <code>cancel</code> 取消; 映射条目格式不对会提示按&quot;键=值&quot;输入</p><h2 id="校验与保存" tabindex="-1">校验与保存 <a class="header-anchor" href="#校验与保存" aria-label="Permalink to “校验与保存”">​</a></h2><ul><li>每次修改字段都立即校验: YAML 必须可解析, 定义 ID 不能为空也不能改 (改了报 <code>id_changed</code>), 定义内容要能被对应解析器读取 (技能走技能解析器, 本地资源走资源解析器). <code>enabled: false</code> 的技能跳过解析校验, 可以先关掉再慢慢改.</li><li>校验通过: 聊天栏提示&quot;成功修改了 %item%&quot;, 并播一个经验球音效; 校验失败: 提示原因并播村民拒绝音效, <strong>修改不生效</strong>. 解析失败 (definition_parse_failed) 的详细原因在控制台.</li><li>修改会记入编辑会话, 由插件在落盘时机统一写入文件: 执行 <code>/eskills reload</code> 之前, 以及插件关闭之前, 都会先把没写盘的修改落盘. 改完想立即生效, 就跑一次 <code>/eskills reload</code>.</li><li>新建和删除会立刻重载模块, 定义马上生效.</li><li>文件被外部程序同时改动时, 写盘会按版本检查拒绝覆盖 (提示冲突), 不会悄悄盖掉别人的修改; 单个定义文本过大也会被拒绝保存</li></ul><h2 id="edit-backups-备份" tabindex="-1">edit-backups 备份 <a class="header-anchor" href="#edit-backups-备份" aria-label="Permalink to “edit-backups 备份”">​</a></h2><p>每次写盘前, 被覆盖的旧文件内容会先备份到:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiSkills/edit-backups/&lt;毫秒时间戳&gt;/&lt;文件名&gt;.yml</span></span></code></pre></div><p>删除定义时也一样: 文件先复制进 <code>edit-backups</code>, 再从定义目录里删掉, 所以确认界面上写的是&quot;此操作不可撤销; 删除前会自动写入 edit-backups 备份&quot;——真删错了, 去备份目录把文件拷回来就行. 备份按时间戳分目录, 不会互相覆盖, 记得定期清理</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to “相关页面”">​</a></h2><ul><li><a href="./commands.html">命令与权限</a>: <code>/eskills edit</code> 的命令入口和权限说明</li><li><a href="./definitions.html">技能定义</a>: 技能与本地资源每个字段的含义和取值</li><li><a href="./triggers.html">触发器</a>: <code>trigger_type</code>, 冲突技能与触发器绑定相关字段</li><li><a href="./script.html">原生脚本系统</a> / <a href="./scripts.html">JS 脚本扩展</a>: <code>script</code> 动作管道与脚本技能的写法</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};